),
prepared as (
  select name,description,price,stock,
    case cat_id
      when 1 then 'Électronique'
      when 2 then 'Mode'
      when 3 then 'Maison'
      when 4 then 'Sports'
      when 5 then 'Livres'
      when 6 then 'Bijoux'
      when 7 then 'Beauté'
      when 8 then 'Auto'
      when 9 then 'Alimentation'
      else null
    end as category_name,
    images,tags
  from raw
)
insert into public.products(name,description,price,stock,category_id,images,tags)
select p.name,p.description,p.price,p.stock,c.id,p.images::jsonb,p.tags::jsonb
from prepared p
join public.categories c on c.name = p.category_name
where not exists(select 1 from public.products existing where existing.name = p.name);
